import{_ as t,c as a,o,ag as i}from"./chunks/framework.dvv-DFtf.js";const p=JSON.parse('{"title":"Resource Detail","description":"","frontmatter":{},"headers":[],"relativePath":"features/resource-detail.md","filePath":"features/resource-detail.md"}'),r={name:"features/resource-detail.md"};function d(l,e,s,c,n,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="resource-detail" tabindex="-1">Resource Detail <a class="header-anchor" href="#resource-detail" aria-label="Permalink to &quot;Resource Detail&quot;">​</a></h1><p>The Resource Detail view provides in-depth information about any Kubernetes resource with multiple viewing formats.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Access the Resource Detail by pressing <code>D</code> (Describe) on any resource, or by navigating into a resource from the list view. This view shows the complete resource specification and status.</p><h2 id="view-modes" tabindex="-1">View Modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to &quot;View Modes&quot;">​</a></h2><p>Toggle between three view modes to see your resource data in the format that works best:</p><h3 id="tree-view-t" tabindex="-1">Tree View (<code>T</code>) <a class="header-anchor" href="#tree-view-t" aria-label="Permalink to &quot;Tree View (`T`)&quot;">​</a></h3><p>Default compact hierarchical tree representation of the resource:</p><ul><li>Collapsible sections</li><li>Quick click-into navigation through nested structures</li><li>Great for viewing complex resources</li></ul><h3 id="yaml-view-y" tabindex="-1">YAML View (<code>Y</code>) <a class="header-anchor" href="#yaml-view-y" aria-label="Permalink to &quot;YAML View (`Y`)&quot;">​</a></h3><p>The view shows the resource as YAML with syntax highlighting:</p><ul><li>Full resource specification</li><li>Color-coded syntax</li><li>Easy to read and copy</li></ul><h3 id="json-view-j" tabindex="-1">JSON View (<code>J</code>) <a class="header-anchor" href="#json-view-j" aria-label="Permalink to &quot;JSON View (`J`)&quot;">​</a></h3><p>Raw JSON format:</p><ul><li>Standard JSON representation</li><li>Syntax highlighted</li><li>Useful for copying to other tools</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="syntax-highlighting" tabindex="-1">Syntax Highlighting <a class="header-anchor" href="#syntax-highlighting" aria-label="Permalink to &quot;Syntax Highlighting&quot;">​</a></h3><p>All view modes feature syntax highlighting for better readability:</p><ul><li>Keys and values are color-coded</li><li>Numbers, strings, and booleans are distinguished</li><li>Comments and annotations are highlighted</li></ul><h3 id="copy-to-clipboard" tabindex="-1">Copy to Clipboard <a class="header-anchor" href="#copy-to-clipboard" aria-label="Permalink to &quot;Copy to Clipboard&quot;">​</a></h3><p>Press <code>C</code> to copy the current view content to your clipboard:</p><ul><li>Copies the full resource in the current format (YAML/JSON)</li><li>Useful for sharing or editing externally</li></ul><h3 id="edit-mode" tabindex="-1">Edit Mode <a class="header-anchor" href="#edit-mode" aria-label="Permalink to &quot;Edit Mode&quot;">​</a></h3><p>Press <code>E</code> to edit the resource:</p><ul><li>Opens in your configured external editor (configured with <code>KUBE_EDITOR</code>, <code>EDITOR</code> or system default)</li><li>Changes are applied when you save and close</li><li>Validation errors are displayed if the update fails</li></ul><h3 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h3><p>The view has an automatic refresh so any changes are updated live. You can still press <code>Ctrl+R</code> to manually refresh the resource detail and fetch the latest state from the cluster.</p><h3 id="secret-decoding" tabindex="-1">Secret Decoding <a class="header-anchor" href="#secret-decoding" aria-label="Permalink to &quot;Secret Decoding&quot;">​</a></h3><p>When viewing Secrets, press <code>X</code> to toggle base64 decoding:</p><ul><li>Decodes all secret values from base64 to plain text</li><li>Helpful for inspecting secret contents without manual decoding</li><li>Toggle off to see the original base64-encoded values</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>T</code></td><td>Switch to Tree view</td></tr><tr><td><code>Y</code></td><td>Switch to YAML view</td></tr><tr><td><code>J</code></td><td>Switch to JSON view</td></tr><tr><td><code>E</code></td><td>Edit resource</td></tr><tr><td><code>C</code></td><td>Copy to clipboard</td></tr><tr><td><code>X</code></td><td>Toggle base64 decode (Secrets)</td></tr><tr><td><code>Ctrl+R</code></td><td>Refresh</td></tr><tr><td><code>Esc</code></td><td>Go back</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Quick Editing</p><p>The Tree view lets you see the structure at a glance before switching to complete YAML for the actual resource definition.</p></div><div class="tip custom-block"><p class="custom-block-title">Keyboard Scrolling</p><p>Use standard scrolling keys (<code>Page Up</code>, <code>Page Down</code>, <code>Home</code>, <code>End</code>) to navigate long resource definitions.</p></div>',35)])])}const f=t(r,[["render",d]]);export{p as __pageData,f as default};
